INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Decentralised Peppol 4-corner (confirmed)', 'This deep-dive page reflects publicly available guidance as of July 2026 and is provided for general awareness, not legal or tax advice. The UK mandate''s technical detail is genuinely unconfirmed pending Budget 2026 — treat anything not explicitly marked "Confirmed" above as a reasonable expectation rather than settled fact, and check GOV.UK directly once the full roadmap is published.', 'The UK has moved from "voluntary and fragmented" to "mandatory with a confirmed network" in under two years — but the fine detail is still being written.', 'The exact file format is one of the few genuinely open questions left — but the direction of travel is unmistakable.', 'The UK mandate''s direction is confirmed — Peppol, 4-corner, no real-time reporting, April 2029 — but the detailed technical standards, exact scope, and any phasing are not yet published; HMRC has committed to a full implementation roadmap at Budget 2026 (November). The UK has deliberately chosen the opposite end of the spectrum from Poland or France here — no clearance authority, and explicitly no live transaction feed to HMRC at launch.', 'Since detailed standards aren''t published, "registration" today is really about positioning yourself well ahead of Budget 2026 — not signing up to anything.', 'No penalty framework exists yet — there''s nothing to enforce until the mandate itself takes effect. These are the practical uncertainties worth tracking instead.' FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Apr 2029', 'Mandatory go-live');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '4-corner', 'Peppol model (confirmed)');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'No CTC', 'No real-time reporting at launch');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2019', 'NHS Peppol mandate already live');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '63%', 'Consultation support for no reporting');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s confirmed', '[["Network standard", "Peppol"], ["Existing public-sector baseline", "BS EN 16931 (Public Procurement Act 2023)"], ["NHS format today", "Peppol BIS Billing 3.0"]]', 'Given NHS suppliers already use Peppol BIS Billing 3.0 and public bodies already accept EN 16931, the most likely landing point is that the general mandate simply extends these existing standards — but this isn''t yet officially confirmed for the wider B2B mandate.', NULL, 'Confirmed', 'confirmed');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s pending', '[["Exact file format", "UBL vs. a UK-specific CIUS \u2014 undecided"], ["Accreditation model", "Not yet published"], ["Scope details", "Exact business-size thresholds, if phased"]]', 'HMRC has explicitly said it will work with stakeholders to weigh adopting an existing international standard against designing something UK-specific — don''t build against a specific schema version yet.', NULL, 'Pending Budget 2026', 'pending');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Current baseline VAT invoice content', '[["Legal basis", "VAT Act 1994 / VAT Regulations 1995"], ["Mandatory fields today", "Supplier/customer details, VAT registration number, invoice date/number, description, net/VAT/gross amounts"]]', 'Whatever structured format eventually lands, it will need to carry all the data already required of a valid UK VAT invoice — nothing about that underlying legal content is expected to change.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Today''s voluntary position', '[["B2B e-invoicing", "Voluntary, by mutual agreement"], ["NHS suppliers", "Mandatory Peppol BIS 3.0 since 2019"], ["Other public bodies", "Must accept EN 16931 e-invoices (reception only)"]]', 'If you already trade with the NHS or another public body, you likely have more Peppol readiness in place today than you might assume — that infrastructure should carry forward into the general mandate.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Model", "4-corner Peppol (decentralised)"], ["Clearance authority", "None"], ["Comparable regime", "Belgium''s first-phase (2026) model"]]', 'This keeps the UK broadly interoperable with EU trading partners despite Brexit removing any legal obligation to align with the EU''s ViDA framework — a deliberate choice to preserve cross-border compatibility.', NULL, 'Confirmed', 'confirmed');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Real-time reporting', '[["At 2029 launch", "Not included"], ["Consultation support", "63% of respondents agreed with this focus"], ["Future possibility", "A later \"5-corner\" HMRC layer isn''t ruled out"]]', 'The government has been explicit that the 2029 mandate won''t require feeding live transaction data to HMRC — but has left the door open to introducing some form of reporting later, once e-invoicing adoption is well established.', NULL, 'Confirmed exclusion', 'confirmed');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Existing public-sector channels', '[["NHS Supply Chain", "Certified Peppol Access Points required today"], ["Public Procurement Act 2023 bodies", "Must accept BS EN 16931 invoices"]]', 'Local authorities connected to Peppol via NHS procurement or existing G-Cloud arrangements already have a head start most other UK businesses don''t.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Making Tax Digital context', '[["Wider programme", "HMRC''s broader tax digitalisation initiative"], ["Long-term ambition", "Pre-populated VAT returns"]]', 'E-invoicing sits inside a much larger UK tax-digitalisation push. Even without real-time reporting today, structured e-invoice data is exactly the kind of input that could eventually feed pre-filled VAT returns down the line.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📏 Phasing by business size', NULL, NULL, 'A phased introduction starting with larger businesses "remains a live possibility" per government commentary, but hasn''t been confirmed either way — Budget 2026 should settle this.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 Penalty framework', NULL, NULL, 'No enforcement or penalty regime has been published. Expect this to arrive alongside the full implementation roadmap rather than before it.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌍 Post-Brexit alignment choice', NULL, NULL, 'The UK has no legal requirement to follow the EU''s ViDA framework post-Brexit, yet has chosen Peppol anyway — a deliberate bet on interoperability with its largest trading partners over designing something wholly independent.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🏥 NHS as the proving ground', NULL, NULL, 'The NHS Supply Chain''s Peppol mandate since 2019 is effectively the UK''s live pilot for the wider 2029 rollout — lessons from NHS supplier onboarding are likely shaping the general design in ways not yet made public.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply the NHS, get Peppol-ready now regardless', 'This obligation already exists independently of the wider 2029 mandate — a certified Peppol Access Point via NHS Supply Chain is not optional if you''re in scope today.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Audit your ERP''s Peppol readiness', 'Given Peppol is now confirmed as the network, check whether your accounting or ERP system already has Peppol connectivity built in, or would need a third-party Access Point.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Consider voluntary bilateral e-invoicing now', 'Nothing stops two trading partners agreeing to exchange structured e-invoices today. Building this muscle early, even informally, reduces the shock of the 2029 deadline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch Budget 2026 closely', 'This is the single most important date on the UK e-invoicing calendar between now and 2029 — the technical standards, accreditation model, and any phasing by business size all land here.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Don''t over-invest in a specific schema yet', 'Because the choice between an existing international standard and a UK-specific CIUS is still open, avoid hard-coding assumptions about exact field-level requirements until the roadmap lands.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.gov.uk/government/consultations/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector/electronic-invoicing-promoting-e-invoicing-across-uk-businesses-and-the-public-sector', 0 FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'GOV.UK — e-invoicing consultation & policy');
